// Use real transit data from the next-ingress endpoint
const firstItem = $input.first()?.json || {};
const ingressUTC = firstItem.ingress_utc;
const nextSign = firstItem.next_sign || 'Aries';
const currentSign = firstItem.current_sign || 'Pisces';
const ingressET = firstItem.ingress_et || ingressUTC;
const blogSlug = firstItem.blog_slug || `moon-enters-${nextSign.toLowerCase()}`;
const signImageUrl = firstItem.sign_image_url || `https://moondaylive.com/assets/signs/${nextSign.toLowerCase()}.png`;
const hoursUntil = firstItem.hours_until || 0;
const blueprintUrl = firstItem.blueprint_url || 'https://moondaylive.com/blueprint';

// Parse the target ingress timestamp
const ingressTime = ingressUTC ? new Date(ingressUTC) : new Date();
const validIngressTime = isNaN(ingressTime.getTime()) ? new Date() : ingressTime;

// Initial target: 1 hour before ingress
let postTime = new Date(validIngressTime.getTime() - 60 * 60 * 1000);

// Quiet-hours math: 7 PM - 5 AM America/New_York
// get NY hour without relying on the server's local timezone
const getNYHour = (d) => parseInt(d.toLocaleString('en-US', { timeZone: 'America/New_York', hour: 'numeric', hour12: false }), 10);
let localHour = getNYHour(postTime);

if (localHour >= 19 || localHour < 5) {
  // Shift to 18:30 America/New_York on the appropriate evening
  const nyDateParts = postTime.toLocaleString('en-US', {
    timeZone: 'America/New_York',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).split(',')[0].split('/');
  const [m, d, y] = nyDateParts;

  let targetDay = postTime;
  if (localHour < 5) {
    targetDay = new Date(postTime.getTime() - 24 * 60 * 60 * 1000);
    const prevParts = targetDay.toLocaleString('en-US', {
      timeZone: 'America/New_York',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit'
    }).split(',')[0].split('/');
    // overwrite m,d,y with previous day's NY date
    [m, d, y] = prevParts;
  }

  // Determine EDT vs EST for the target day
  const offsetName = new Date(`${y}-${m}-${d}T18:30:00`).toLocaleString('en-US', {
    timeZone: 'America/New_York',
    timeZoneName: 'short'
  }).match(/[A-Z]{3,4}$/)[0];
  const offset = offsetName === 'EDT' ? '-04:00' : '-05:00';

  postTime = new Date(`${y}-${m}-${d}T18:30:00${offset}`);
}

// Generate blog content using real data
const blogDraft = `As the Moon transitions from ${currentSign} into ${nextSign}, we enter a powerful shift in emotional currents and collective energy. This alignment invites us to reflect on how we ground our inner intuitive realizations into focused, intentional momentum. Explore how this dynamic influences your daily rhythm and emotional landscape as we navigate this celestial threshold together.

The Moon enters ${nextSign} on ${ingressET}. Visit your Moonday blueprint at ${blueprintUrl} to see how this transit touches your personal Lunar Signature.`;

// Generate expanded Reddit content
const redditDraft = `Hey r/moondaylive! 🌙 The Moon is officially shifting from ${currentSign} into ${nextSign}.

This transition brings a fascinating pivot in our collective emotional weather, moving us from the reflective depths into a renewed wave of initiation and drive.

The Moon enters ${nextSign} on ${ingressET}. How are you tracking this energy today? Drop your thoughts below!

*(Not sure where your natal Moon sits for this transit? Head over to ${blueprintUrl} to run an extensive personal evaluation.)*`;

return [{
  json: {
    resumeAt: postTime.toISOString(),
    currentSign,
    nextSign,
    ingressUTC: ingressUTC || new Date().toISOString(),
    ingressET,
    label: `Moon ${currentSign} → ${nextSign}`,
    hoursUntilIngress: hoursUntil,
    blog_slug: blogSlug,
    sign_image_url: signImageUrl,
    blueprint_url: blueprintUrl,
    blog_content: blogDraft,
    reddit_content: redditDraft
  }
}];
